functions AS (select p.oid::regprocedure::text signature,md5(pg_get_functiondef(p.oid)) definition_hash,p.prosecdef security_definer,p.proconfig config,p.proacl::text acl from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f' and p.proname ~ '^(tax_|.*finance_|expense_|payout_|treasury_|money_|cash_)' order by 1),
catalog AS (select c.relname name,c.relrowsecurity rls,c.relacl::text acl,
 (select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped) columns,
 (select coalesce(jsonb_agg(jsonb_build_object('name',x.conname,'definition',pg_get_constraintdef(x.oid)) order by x.conname),'[]') from pg_constraint x where x.conrelid=c.oid) constraints,
 (select coalesce(jsonb_agg(pg_get_triggerdef(t.oid) order by t.tgname),'[]') from pg_trigger t where t.tgrelid=c.oid and not t.tgisinternal) triggers,
 (select coalesce(jsonb_agg(indexdef order by indexname),'[]') from pg_indexes i where i.schemaname='public' and i.tablename=c.relname) indexes,
 (select coalesce(jsonb_agg(to_jsonb(p) order by p.policyname),'[]') from pg_policies p where p.schemaname='public' and p.tablename=c.relname) policies
 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname like 'finance_%' order by 1),
all_public_functions AS (
 SELECT p.oid::regprocedure::text signature, pg_get_userbyid(p.proowner) owner,
        pg_get_functiondef(p.oid) definition, md5(pg_get_functiondef(p.oid)) definition_hash,
        p.proacl::text acl, p.prosecdef security_definer, p.proconfig config
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname='public' AND p.prokind IN ('f','p') ORDER BY 1
),
security_context AS (
 SELECT c.relname name,pg_get_userbyid(c.relowner) owner,c.relrowsecurity rls,
        c.relforcerowsecurity force_rls,c.relacl::text acl
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','S') ORDER BY 1
),
default_privileges AS (
 SELECT pg_get_userbyid(d.defaclrole) owner,coalesce(n.nspname,'*') schema,
        d.defaclobjtype object_type,d.defaclacl::text acl
 FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace
 WHERE d.defaclnamespace=0 OR n.nspname='public' ORDER BY 1,2,3
),
role_membership AS (
 SELECT parent.rolname granted_role,member.rolname member,m.admin_option
 FROM pg_auth_members m JOIN pg_roles parent ON parent.oid=m.roleid
 JOIN pg_roles member ON member.oid=m.member
 WHERE parent.rolname IN ('anon','authenticated','service_role','postgres')
    OR member.rolname IN ('anon','authenticated','service_role','postgres') ORDER BY 1,2
)
